package io.github.mehrdad_abdi.qintar.data.quran

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase

/**
 * The bundled Quran text and structure (DESIGN.md §7.4), opened from `assets/quran.db`.
 *
 * The asset is generated by `tools/quran-data/build_quran_db.py`, which stamps it with
 * `PRAGMA user_version = VERSION`. When the data changes, bump [VERSION] here and
 * `ROOM_VERSION` in the generator together: Room then discards the old copy and copies the
 * new asset. Destructive fallback is acceptable only because this database holds no user data.
 */
@Database(
    entities = [SurahEntity::class, AyahEntity::class],
    version = QuranDatabase.VERSION,
    exportSchema = true,
)
abstract class QuranDatabase : RoomDatabase() {

    abstract fun quranDao(): QuranDao

    companion object {
        const val VERSION = 1
        const val ASSET_PATH = "quran.db"
        const val FILE_NAME = "quran.db"

        fun create(context: Context): QuranDatabase =
            Room.databaseBuilder(context, QuranDatabase::class.java, FILE_NAME)
                .createFromAsset(ASSET_PATH)
                .fallbackToDestructiveMigration(dropAllTables = true)
                .build()
    }
}
